          "code": "import numpy as np\n\n\ndef sigmoid(z: np.ndarray) -> np.ndarray:\n    return 1.0 / (1.0 + np.exp(-np.clip(z, -30.0, 30.0)))\n\n\ndef structure_score(G: float, H: float, reg_lambda: float) -> float:\n    return (G * G) / (H + reg_lambda)\n\n\ndef sparsity_aware_split_finder(\n    x: np.ndarray,\n    g: np.ndarray,\n    h: np.ndarray,\n    reg_lambda: float = 1.0,\n    gamma: float = 0.0,\n    min_child_weight: float = 1.0,\n) -> dict:\n    \"\"\"Algoritma 3 Chen & Guestrin (2016): Sparsity-Aware Split Finding orde-2.\"\"\"\n    is_miss = np.isnan(x)\n    x_obs = x[~is_miss]\n    g_obs = g[~is_miss]\n    h_obs = h[~is_miss]\n\n    G_total = float(np.sum(g))\n    H_total = float(np.sum(h))\n    parent_score = structure_score(G_total, H_total, reg_lambda)\n\n    order = np.argsort(x_obs)\n    xs = x_obs[order]\n    gs = g_obs[order]\n    hs = h_obs[order]\n\n    best = {\n        \"gain\": -np.inf,\n        \"threshold\": None,\n        \"default_dir\": \"right\",\n        \"w_left\": 0.0,\n        \"w_right\": 0.0,\n    }\n\n    # Lintasan 1: arahkan semua missing (NaN) ke KANAN (scan kiri -> kanan)\n    G_L, H_L = 0.0, 0.0\n    for i in range(len(xs) - 1):\n        G_L += float(gs[i])\n        H_L += float(hs[i])\n        if xs[i] == xs[i + 1]:\n            continue\n        G_R = G_total - G_L\n        H_R = H_total - H_L\n        if H_L < min_child_weight or H_R < min_child_weight:\n            continue\n        gain = 0.5 * (\n            structure_score(G_L, H_L, reg_lambda)\n            + structure_score(G_R, H_R, reg_lambda)\n            - parent_score\n        ) - gamma\n        if gain > best[\"gain\"]:\n            best = {\n                \"gain\": gain,\n                \"threshold\": 0.5 * float(xs[i] + xs[i + 1]),\n                \"default_dir\": \"right\",\n                \"w_left\": -G_L / (H_L + reg_lambda),\n                \"w_right\": -G_R / (H_R + reg_lambda),\n            }\n\n    # Lintasan 2: arahkan semua missing (NaN) ke KIRI (scan kanan -> kiri)\n    G_R, H_R = 0.0, 0.0\n    for i in range(len(xs) - 1, 0, -1):\n        G_R += float(gs[i])\n        H_R += float(hs[i])\n        if xs[i] == xs[i - 1]:\n            continue\n        G_L = G_total - G_R\n        H_L = H_total - H_R\n        if H_L < min_child_weight or H_R < min_child_weight:\n            continue\n        gain = 0.5 * (\n            structure_score(G_L, H_L, reg_lambda)\n            + structure_score(G_R, H_R, reg_lambda)\n            - parent_score\n        ) - gamma\n        if gain > best[\"gain\"]:\n            best = {\n                \"gain\": gain,\n                \"threshold\": 0.5 * float(xs[i - 1] + xs[i]),\n                \"default_dir\": \"left\",\n                \"w_left\": -G_L / (H_L + reg_lambda),\n                \"w_right\": -G_R / (H_R + reg_lambda),\n            }\n    return best\n\n\nrng = np.random.default_rng(42)\nn = 400\n# Fitur skor biro kredit: 25% nasabah thin-file berstatus NaN dengan risiko default tinggi (MNAR!)\nx_feat = rng.normal(0.0, 1.0, size=n)\nis_thin_file = rng.random(n) < 0.25\nlogits_true = np.where(is_thin_file, 1.6, np.where(x_feat < -0.2, 1.2, -1.5))\ny = (rng.random(n) < sigmoid(logits_true)).astype(float)\nx_with_nan = x_feat.copy()\nx_with_nan[is_thin_file] = np.nan\n\n# Gradien & Hessian Log-Loss pada skor awal F^(0) = log(p/(1-p))\np0 = np.full(n, np.mean(y))\ng_vec = p0 - y\nh_vec = p0 * (1.0 - p0)\n\nprint(\"=== 1. Sparsity-Aware Split Finding (MNAR: NaN Bersifat Risiko Tinggi) ===\")\nres_nan = sparsity_aware_split_finder(x_with_nan, g_vec, h_vec, reg_lambda=1.0, gamma=0.0)\nprint(\n    f\"Native NaN Split   -> thr={res_nan['threshold']:+.3f} | default_dir={res_nan['default_dir']:5s} \"\n    f\"| gain={res_nan['gain']:.4f} | w_L={res_nan['w_left']:+.3f} | w_R={res_nan['w_right']:+.3f}\"\n)\n\n# Bandingkan dengan imputasi median (memaksa NaN menyatu ke tengah populasi non-risiko!)\nx_med = np.where(np.isnan(x_with_nan), np.nanmedian(x_with_nan), x_with_nan)\nres_med = sparsity_aware_split_finder(x_med, g_vec, h_vec, reg_lambda=1.0, gamma=0.0)\nprint(\n    f\"Imputasi Median    -> thr={res_med['threshold']:+.3f} | default_dir=N/A   \"\n    f\"| gain={res_med['gain']:.4f} | w_L={res_med['w_left']:+.3f} | w_R={res_med['w_right']:+.3f}\"\n)\n\nprint(\"\\n=== 2. Pengaruh Regularisasi L2 (lambda) & Pruning Threshold (gamma) pada Bobot Daun ===\")\nprint(\"lambda | gamma | Gain Bersih | Keputusan Split | w_left  | w_right\")\nprint(\"-\" * 68)\nfor lam, gam in [(0.1, 0.0), (1.0, 0.0), (10.0, 0.0), (50.0, 0.0), (1.0, 30.0), (1.0, 80.0)]:\n    r = sparsity_aware_split_finder(x_with_nan, g_vec, h_vec, reg_lambda=lam, gamma=gam)\n    status = \"BELAH (gain>0)\" if r[\"gain\"] > 0.0 else \"PANGKAS (prune)\"\n    print(f\"{lam:6.1f} | {gam:5.1f} | {r['gain']:11.4f} | {status:15s} | {r['w_left']:+7.4f} | {r['w_right']:+7.4f}\")",
          "expectedOutput": "=== 1. Sparsity-Aware Split Finding (MNAR: NaN Bersifat Risiko Tinggi) ===\nNative NaN Split   -> thr=-0.214 | default_dir=left  | gain=76.1597 | w_L=+1.045 | w_R=-1.448\nImputasi Median    -> thr=-0.029 | default_dir=N/A   | gain=59.8051 | w_L=+0.827 | w_R=-1.437\n\n=== 2. Pengaruh Regularisasi L2 (lambda) & Pruning Threshold (gamma) pada Bobot Daun ===\nlambda | gamma | Gain Bersih | Keputusan Split | w_left  | w_right\n--------------------------------------------------------------------\n   0.1 |   0.0 |     77.6227 | BELAH (gain>0)  | +1.0612 | -1.4796\n   1.0 |   0.0 |     76.1597 | BELAH (gain>0)  | +1.0449 | -1.4480\n  10.0 |   0.0 |     64.1257 | BELAH (gain>0)  | +0.9055 | -1.1935\n  50.0 |   0.0 |     37.8378 | BELAH (gain>0)  | +0.5685 | -0.6700\n   1.0 |  30.0 |     46.1597 | BELAH (gain>0)  | +1.0449 | -1.4480\n   1.0 |  80.0 |     -3.8403 | PANGKAS (prune) | +1.0449 | -1.4480",
