          "code": "import os\nos.environ[\"OMP_NUM_THREADS\"] = \"1\"\nimport numpy as np\nimport pandas as pd\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import log_loss, roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold, train_test_split\nfrom sklearn.preprocessing import TargetEncoder\n\nrng = np.random.default_rng(164)\nn = 1600\n\n# Fitur kategorikal kardinalitas tinggi (350 agensi, mayoritas berfrekuensi rendah 2-6 baris -> rawan target leakage!)\nn_cats = 350\n# Sinyal lemah dari kategori + sinyal sedang dari 2 fitur numerik\ncat_true_eff = rng.normal(0.0, 0.35, size=n_cats)\ncat_ids = rng.integers(0, n_cats, size=n)\nx_num = rng.normal(0.0, 1.0, size=(n, 3))\n\nlogit = 0.9 * x_num[:, 0] - 0.8 * x_num[:, 1] + cat_true_eff[cat_ids]\ny = (rng.random(n) < (1.0 / (1.0 + np.exp(-logit)))).astype(int)\n\ncat_str = np.array([f\"agency_{c:03d}\" for c in cat_ids])\nidx_tr, idx_te = train_test_split(np.arange(n), test_size=0.30, stratify=y, random_state=42)\n\n# 1. ANTI-PATTERN A: Naive Target Encoding (pakai rata-rata seluruh train termasuk y_i sendiri!)\ns_tr = pd.Series(y[idx_tr]).groupby(cat_str[idx_tr]).agg([\"sum\", \"count\"])\np_glob = float(np.mean(y[idx_tr]))\nnaive_map = (s_tr[\"sum\"] / s_tr[\"count\"]).to_dict()\ntr_naive = np.array([naive_map[c] for c in cat_str[idx_tr]])\nte_naive = np.array([naive_map.get(c, p_glob) for c in cat_str[idx_te]])\n\n# 2. ANTI-PATTERN B: Leave-One-Out (LOO) Target Encoding tanpa smoothing\ntr_loo = np.array(\n    [\n        (s_tr.loc[c, \"sum\"] - y[i]) / (s_tr.loc[c, \"count\"] - 1) if s_tr.loc[c, \"count\"] > 1 else p_glob\n        for i, c in zip(idx_tr, cat_str[idx_tr])\n    ]\n)\nte_loo = te_naive.copy()\n\n# 3. SAFE SKLEARN: Cross-Fitted Smoothed TargetEncoder (Sklearn 1.3–1.9+)\nte_enc = TargetEncoder(\n    smooth=\"auto\",\n    target_type=\"binary\",\n    cv=StratifiedKFold(n_splits=5, shuffle=True, random_state=42),\n)\ntr_oof = te_enc.fit_transform(cat_str[idx_tr].reshape(-1, 1), y[idx_tr]).ravel()\nte_oof = te_enc.transform(cat_str[idx_te].reshape(-1, 1)).ravel()\n\n# 4. SAFE CATBOOST-STYLE: Online Permutation Ordered Target Statistics (a=15)\nperm = rng.permutation(len(idx_tr))\ntr_ord = np.empty(len(idx_tr), dtype=float)\nsm, cm = {}, {}\nfor pos in perm:\n    c = cat_str[idx_tr[pos]]\n    tr_ord[pos] = (sm.get(c, 0.0) + 15.0 * p_glob) / (cm.get(c, 0) + 15.0)\n    sm[c] = sm.get(c, 0.0) + float(y[idx_tr[pos]])\n    cm[c] = cm.get(c, 0) + 1\nte_ord = np.array([(sm.get(c, 0.0) + 15.0 * p_glob) / (cm.get(c, 0) + 15.0) for c in cat_str[idx_te]])\n\nprint(\"=== Perbandingan Target Encoding pada Kardinalitas Tinggi (350 Kategori, HistGBDT) ===\")\nprint(\"Metode Encoding              | Train AUC | Test AUC | Test Log-Loss | Overfit Gap AUC\")\nprint(\"-\" * 85)\nfor name, c_tr, c_te in [\n    (\"Naive Mean TE (BOCOR PARAH) \", tr_naive, te_naive),\n    (\"Leave-One-Out (LOO Trap!)   \", tr_loo, te_loo),\n    (\"Sklearn TargetEncoder (OOF) \", tr_oof, te_oof),\n    (\"Ordered TS (CatBoost Style) \", tr_ord, te_ord),\n]:\n    Xtr_m = np.column_stack([x_num[idx_tr], c_tr])\n    Xte_m = np.column_stack([x_num[idx_te], c_te])\n    clf = HistGradientBoostingClassifier(max_iter=70, max_depth=4, learning_rate=0.07, l2_regularization=3.0, random_state=42)\n    clf.fit(Xtr_m, y[idx_tr])\n    p_tr = clf.predict_proba(Xtr_m)[:, 1]\n    p_te = clf.predict_proba(Xte_m)[:, 1]\n    auc_tr = roc_auc_score(y[idx_tr], p_tr)\n    auc_te = roc_auc_score(y[idx_te], p_te)\n    print(f\"{name:28s} | {auc_tr:9.4f} | {auc_te:8.4f} | {log_loss(y[idx_te], p_te):13.4f} | {auc_tr - auc_te:+15.4f}\")",
          "expectedOutput": "=== Perbandingan Target Encoding pada Kardinalitas Tinggi (350 Kategori, HistGBDT) ===\nMetode Encoding              | Train AUC | Test AUC | Test Log-Loss | Overfit Gap AUC\n-------------------------------------------------------------------------------------\nNaive Mean TE (BOCOR PARAH)  |    0.9188 |   0.5790 |        1.0432 |         +0.3398\nLeave-One-Out (LOO Trap!)    |    0.8417 |   0.7259 |        0.6170 |         +0.1158\nSklearn TargetEncoder (OOF)  |    0.8395 |   0.7258 |        0.6175 |         +0.1137\nOrdered TS (CatBoost Style)  |    0.8399 |   0.7265 |        0.6174 |         +0.1134",
