          "code": "import numpy as np\n\nrng = np.random.default_rng(165)\n\n# Audit 1A: Kasus Ekstrem Seimbang (2 Pos, 2 Neg per Kategori) -> LOO Bocor Sempurna (-1.0)\ny_bal = np.tile([0.0, 0.0, 1.0, 1.0], 100)\nloo_bal = np.array([(2.0 - yi) / 3.0 for yi in y_bal])\n\n# Audit 1B: 250 Kategori Noise Murni i.i.d. Bernoulli(p=0.5), masing-masing 4 baris\nn_cats = 250\ncats_iid = np.repeat(np.arange(n_cats), 4)\ny_iid = rng.binomial(1, 0.5, size=4 * n_cats).astype(float)\np_prior = float(np.mean(y_iid))\n\nsum_by_cat = np.bincount(cats_iid, weights=y_iid)\ncnt_by_cat = np.bincount(cats_iid)\nnaive_iid = sum_by_cat[cats_iid] / cnt_by_cat[cats_iid]\nnaive_shift = float(np.mean(naive_iid[y_iid == 1]) - np.mean(naive_iid[y_iid == 0]))\n\n# Hitung Ordered TS (rata-rata shift & korelasi lintas 20 permutasi acak, prior_weight a=5.0)\nord_corrs, ord_shifts = [], []\nfor s in range(20):\n    r_p = np.random.default_rng(100 + s)\n    perm = r_p.permutation(len(y_iid))\n    enc = np.empty(len(y_iid), dtype=float)\n    sm, cm = {}, {}\n    for idx in perm:\n        c = cats_iid[idx]\n        enc[idx] = (sm.get(c, 0.0) + 5.0 * p_prior) / (cm.get(c, 0) + 5.0)\n        sm[c] = sm.get(c, 0.0) + y_iid[idx]\n        cm[c] = cm.get(c, 0) + 1\n    ord_corrs.append(float(np.corrcoef(enc, y_iid)[0, 1]))\n    ord_shifts.append(float(np.mean(enc[y_iid == 1]) - np.mean(enc[y_iid == 0])))\n\nprint(\"=== 1. Audit Kebocoran Target (Syarat P1): Naive vs LOO vs Ordered TS (n_c=4) ===\")\nprint(f\"Naive TE (250 kat i.i.d. noise)  : E[x|y=1]-E[x|y=0] = {naive_shift:+.4f} | Corr(enc, y) = {np.corrcoef(naive_iid, y_iid)[0,1]:+.4f} (BOCOR POSITIF!)\")\nprint(f\"LOO (per kategori seimbang 2P/2N): x(y=1)-x(y=0)     = {loo_bal[2]-loo_bal[0]:+.4f} | Corr(enc, y) = {np.corrcoef(loo_bal, y_bal)[0,1]:+.4f} (BOCOR NEGATIF!)\")\nprint(f\"Ordered TS (250 kat i.i.d., a=5) : E[x|y=1]-E[x|y=0] = {np.mean(ord_shifts):+.4f} | Corr(enc, y) = {np.mean(ord_corrs):+.4f} (NOL LEAKAGE P1!)\")\n\n# Audit 2: Sensitivitas Prior Weight (a) Ordered TS pada Kategori Langka vs Sering\nprint(\"\\n=== 2. Audit Sensitivitas Smoothing Prior (a) Ordered TS pada Kategori Berfrekuensi Berbeda ===\")\nprint(\"Prior a | MSE Estimasi Kategori Langka (n=3) | MSE Estimasi Kategori Sering (n=50) | Bias-Varians\")\nprint(\"-\" * 98)\ntrue_p_rare, true_p_freq = 0.70, 0.70\np_glob = 0.25\nobs_rare = rng.binomial(1, true_p_rare, size=(300, 3)).sum(axis=1)\nobs_freq = rng.binomial(1, true_p_freq, size=(300, 50)).sum(axis=1)\nfor a in [0.2, 1.0, 2.5, 10.0, 40.0]:\n    est_rare = (obs_rare + a * p_glob) / (3.0 + a)\n    est_freq = (obs_freq + a * p_glob) / (50.0 + a)\n    mse_r = float(np.mean((est_rare - true_p_rare) ** 2))\n    mse_f = float(np.mean((est_freq - true_p_freq) ** 2))\n    note = \"Varians tinggi (langka)\" if a < 0.8 else (\"Titik manis bias-varians\" if a <= 3.0 else \"Bias penyusutan ke prior naik\")\n    print(f\"{a:7.1f} | {mse_r:34.4f} | {mse_f:35.4f} | {note}\")",
