          "id": "code-ml-16-4-ch16_4_scratch",
          "title": "First-Principles NumPy: Multi-Target Vector-Leaf Split Finder (C=3) & Temperature Scaling ECE",
          "language": "python",
          "filename": "16_4_vector_leaf_temperature_calibration_scratch.py",
          "code": "import numpy as np\n\n\ndef multi_target_vector_leaf_split(\n    X: np.ndarray,\n    G: np.ndarray,\n    H: np.ndarray,\n    reg_lambda: float = 1.0,\n    gamma: float = 0.0,\n) -> dict:\n    \"\"\"Vector-Leaf Split Finder (XGBoost 2/3 multi_output_tree): 1 belahan bersama untuk C target.\"\"\"\n    n, d = X.shape\n    C = G.shape[1]\n    G_tot = G.sum(axis=0)\n    H_tot = H.sum(axis=0)\n    parent_score = float(np.sum((G_tot ** 2) / (H_tot + reg_lambda)))\n\n    best = {\"gain\": -np.inf, \"feat\": -1, \"thr\": 0.0, \"w_left\": np.zeros(C), \"w_right\": np.zeros(C)}\n    for f in range(d):\n        order = np.argsort(X[:, f])\n        xs = X[order, f]\n        Gs = np.cumsum(G[order], axis=0)\n        Hs = np.cumsum(H[order], axis=0)\n        valid = np.where(xs[:-1] < xs[1:])[0]\n        if len(valid) == 0:\n            continue\n        GL = Gs[valid]\n        HL = Hs[valid]\n        GR = G_tot[None, :] - GL\n        HR = H_tot[None, :] - HL\n        scores = np.sum((GL ** 2) / (HL + reg_lambda) + (GR ** 2) / (HR + reg_lambda), axis=1)\n        gains = 0.5 * (scores - parent_score) - gamma\n        k_best = int(np.argmax(gains))\n        if float(gains[k_best]) > best[\"gain\"]:\n            v_idx = int(valid[k_best])\n            best = {\n                \"gain\": float(gains[k_best]),\n                \"feat\": f,\n                \"thr\": 0.5 * float(xs[v_idx] + xs[v_idx + 1]),\n                \"w_left\": -GL[k_best] / (HL[k_best] + reg_lambda),\n                \"w_right\": -GR[k_best] / (HR[k_best] + reg_lambda),\n            }\n    return best\n\n\ndef compute_ece(y_true: np.ndarray, probs: np.ndarray, n_bins: int = 10) -> float:\n    edges = np.linspace(0.0, 1.0, n_bins + 1)\n    ece = 0.0\n    n = len(y_true)\n    for lo, hi in zip(edges[:-1], edges[1:]):\n        mask = (probs >= lo) & (probs <= hi if hi == 1.0 else probs < hi)\n        if np.any(mask):\n            ece += (np.sum(mask) / n) * abs(float(np.mean(y_true[mask])) - float(np.mean(probs[mask])))\n    return float(ece)\n\n\nrng = np.random.default_rng(166)\n# 1. Demo Vector-Leaf Split pada 3 target risiko berkorelasi (C=3)\nn_m = 400\nX_m = rng.normal(0.0, 1.0, size=(n_m, 4))\n# Faktor laten bersama pada X[:, 0] > 0 memengaruhi 3 target sekaligus\nY_m = np.column_stack(\n    [\n        np.where(X_m[:, 0] > 0.0, 2.0, -1.8) + rng.normal(0.0, 0.5, size=n_m),\n        np.where(X_m[:, 0] > 0.0, 1.5, -1.2) + 0.4 * X_m[:, 1] + rng.normal(0.0, 0.5, size=n_m),\n        np.where(X_m[:, 0] > 0.0, -1.6, 1.4) + rng.normal(0.0, 0.5, size=n_m),\n    ]\n)\n# Untuk MSE dari prediksi awal 0: g_ic = -y_ic, h_ic = 1.0\nG_m = -Y_m\nH_m = np.ones_like(Y_m)\nres_vec = multi_target_vector_leaf_split(X_m, G_m, H_m, reg_lambda=2.0, gamma=0.5)\n\nprint(\"=== 1. Multi-Target Vector-Leaf Split Finder (1 Pohon Bersama untuk C=3 Target) ===\")\nprint(f\"Fitur split terbaik : X[{res_vec['feat']}] <= {res_vec['thr']:+.4f} | Joint Gain = {res_vec['gain']:.2f}\")\nprint(f\"Vektor bobot w_left : {np.round(res_vec['w_left'], 3).tolist()}\")\nprint(f\"Vektor bobot w_right: {np.round(res_vec['w_right'], 3).tolist()}\")\n\n# 2. Post-Boosting Temperature Scaling pada Log-Odds GBDT yang Overconfident\nlogits_true = rng.normal(0.0, 1.4, size=1000)\np_true = 1.0 / (1.0 + np.exp(-logits_true))\ny_cal = (rng.random(1000) < p_true).astype(float)\n# Simulasi GBDT iterasi terlalu panjang: log-odds mengembang 2.4x (overconfident!)\nraw_logits = 2.4 * logits_true + 0.25\np_raw = 1.0 / (1.0 + np.exp(-raw_logits))\n\n# Optimasi suhu T (Temperature Scaling) dengan grid halus meminimalkan Log-Loss pada 500 sampel kalibrasi\nbest_T, best_nll = 1.0, np.inf\nfor T in np.linspace(0.5, 4.0, 71):\n    p_t = 1.0 / (1.0 + np.exp(-raw_logits[:500] / T))\n    p_t = np.clip(p_t, 1e-12, 1.0 - 1e-12)\n    nll = -float(np.mean(y_cal[:500] * np.log(p_t) + (1.0 - y_cal[:500]) * np.log(1.0 - p_t)))\n    if nll < best_nll:\n        best_nll, best_T = nll, float(T)\n\np_scaled_te = 1.0 / (1.0 + np.exp(-raw_logits[500:] / best_T))\np_raw_te = p_raw[500:]\ny_te = y_cal[500:]\n\nprint(\"\\n=== 2. Kalibrasi Probabilitas Pasca-Boosting (Temperature Scaling, Held-Out Test) ===\")\nprint(f\"Suhu optimal T*     : {best_T:.2f}\")\nprint(f\"Raw Overconfident   : Brier={np.mean((p_raw_te - y_te)**2):.4f} | ECE={compute_ece(y_te, p_raw_te):.4f}\")\nprint(f\"Temperature Scaled  : Brier={np.mean((p_scaled_te - y_te)**2):.4f} | ECE={compute_ece(y_te, p_scaled_te):.4f}\")",
