          "code": "import os\nos.environ[\"OMP_NUM_THREADS\"] = \"1\"\nimport numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import brier_score_loss, log_loss, roc_auc_score\nfrom sklearn.model_selection import train_test_split\n\n\ndef expected_calibration_error(y_true: np.ndarray, probs: np.ndarray, n_bins: int = 10) -> float:\n    edges = np.linspace(0.0, 1.0, n_bins + 1)\n    ece = 0.0\n    n = len(y_true)\n    for lo, hi in zip(edges[:-1], edges[1:]):\n        mask = (probs >= lo) & (probs <= hi if hi == 1.0 else probs < hi)\n        if np.any(mask):\n            ece += (np.sum(mask) / n) * abs(float(np.mean(y_true[mask])) - float(np.mean(probs[mask])))\n    return float(ece)\n\n\nX, y = make_classification(\n    n_samples=1200,\n    n_features=14,\n    n_informative=6,\n    n_redundant=3,\n    flip_y=0.08,\n    weights=[0.70, 0.30],\n    random_state=42,\n)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.30, stratify=y, random_state=42)\n\n# GBDT over-boosted (learning_rate=0.22, min_samples_leaf=5, L2=0) mendorong probabilitas ekstrem 0/1!\nbase_params = dict(\n    max_iter=90,\n    max_depth=6,\n    max_leaf_nodes=31,\n    min_samples_leaf=5,\n    learning_rate=0.22,\n    l2_regularization=0.0,\n    random_state=42,\n)\nraw_hgb = HistGradientBoostingClassifier(**base_params).fit(X_tr, y_tr)\ncal_sigmoid = CalibratedClassifierCV(\n    estimator=HistGradientBoostingClassifier(**base_params), method=\"sigmoid\", cv=3\n).fit(X_tr, y_tr)\ncal_isotonic = CalibratedClassifierCV(\n    estimator=HistGradientBoostingClassifier(**base_params), method=\"isotonic\", cv=3\n).fit(X_tr, y_tr)\n\nprint(\"=== Kalibrasi Probabilitas Pasca-Boosting pada HistGBDT (ROC-AUC vs Brier vs ECE) ===\")\nprint(\"Model / Metode Kalibrasi         | ROC-AUC | Log-Loss | Brier Score | 10-Bin ECE\")\nprint(\"-\" * 82)\nfor label, mdl in [\n    (\"Raw HistGBDT (Overconfident)    \", raw_hgb),\n    (\"Platt / Sigmoid Calibration (CV)\", cal_sigmoid),\n    (\"Isotonic Calibration (CV)       \", cal_isotonic),\n]:\n    p = mdl.predict_proba(X_te)[:, 1]\n    print(\n        f\"{label:32s} | {roc_auc_score(y_te, p):7.4f} | {log_loss(y_te, p):8.4f} \"\n        f\"| {brier_score_loss(y_te, p):11.4f} | {expected_calibration_error(y_te, p):10.4f}\"\n    )",
