          "title": "XGBoost 3.4 Produksi Nyata: Vector Leaves (multi_output_tree) vs One-Per-Tree + UBJ/JSON + SHA-256",
          "language": "python",
          "filename": "16_4_xgboost_real_vector_leaves_ubj_audit.py",
          "code": "import hashlib\nimport os\nimport tempfile\nimport numpy as np\nimport xgboost as xgb\nfrom sklearn.metrics import root_mean_squared_error\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(168)\nn = 1200\nX = rng.normal(0.0, 1.0, size=(n, 10))\n# 3 target risiko simultan yang berbagi faktor laten non-linier kuat (skenario ideal Vector Leaves!)\nshared_latent = 2.2 * np.sin(X[:, 0]) + 1.5 * X[:, 1] * X[:, 2] - 1.2 * np.maximum(X[:, 3], 0.0)\nY = np.column_stack(\n    [\n        shared_latent + 0.6 * X[:, 4] + rng.normal(0.0, 0.4, size=n),\n        -0.8 * shared_latent + 0.7 * X[:, 5] + rng.normal(0.0, 0.4, size=n),\n        1.1 * shared_latent - 0.5 * X[:, 4] + rng.normal(0.0, 0.4, size=n),\n    ]\n)\nX_tr, X_te, Y_tr, Y_te = train_test_split(X, Y, test_size=0.30, random_state=42)\n\n# 1. Strategi klasik: one_output_per_tree (50 iterasi x 3 target = 150 pohon terpisah)\nm_one = xgb.XGBRegressor(\n    n_estimators=50,\n    max_depth=5,\n    learning_rate=0.08,\n    tree_method=\"hist\",\n    multi_strategy=\"one_output_per_tree\",\n    reg_lambda=2.0,\n    random_state=42,\n    n_jobs=1,\n).fit(X_tr, Y_tr)\n\n# 2. Strategi modern XGBoost 2/3: multi_output_tree (50 pohon tunggal ber-daun vektor R^3!)\nm_vec = xgb.XGBRegressor(\n    n_estimators=50,\n    max_depth=5,\n    learning_rate=0.08,\n    tree_method=\"hist\",\n    multi_strategy=\"multi_output_tree\",\n    reg_lambda=2.0,\n    random_state=42,\n    n_jobs=1,\n).fit(X_tr, Y_tr)\n\nprint(f\"=== Benchmark Multi-Target XGBoost {xgb.__version__}: One-Per-Tree vs Vector Leaves & Serialisasi UBJ/JSON ===\")\nwith tempfile.TemporaryDirectory() as tmpdir:\n    for name, mdl in [\n        (\"one_output_per_tree (K*C pohon)\", m_one),\n        (\"multi_output_tree (Vector Leaf)\", m_vec),\n    ]:\n        preds = mdl.predict(X_te)\n        rmse_all = float(root_mean_squared_error(Y_te, preds))\n        n_trees = mdl.get_booster().num_boosted_rounds()\n        total_dump_trees = len(mdl.get_booster().get_dump(dump_format=\"json\"))\n\n        p_ubj = os.path.join(tmpdir, \"model.ubj\")\n        p_json = os.path.join(tmpdir, \"model.json\")\n        mdl.save_model(p_ubj)\n        mdl.save_model(p_json)\n        kb_ubj = os.path.getsize(p_ubj) / 1024.0\n        kb_json = os.path.getsize(p_json) / 1024.0\n\n        # Verifikasi integritas reload bit-exact dari format native UBJ (aman, bebas pickle RCE!)\n        reloaded = xgb.XGBRegressor()\n        reloaded.load_model(p_ubj)\n        max_diff = float(np.max(np.abs(preds - reloaded.predict(X_te))))\n        sha_prefix = hashlib.sha256(open(p_ubj, \"rb\").read()).hexdigest()[:12]\n\n        print(\n            f\"{name:31s} | RMSE={rmse_all:.4f} | Pohon={total_dump_trees:3d} \"\n            f\"| UBJ={kb_ubj:5.1f}KB vs JSON={kb_json:5.1f}KB | ReloadDiff={max_diff:.1e} | SHA256={sha_prefix}\"\n        )",
          "expectedOutput": "=== Benchmark Multi-Target XGBoost 3.4.0: One-Per-Tree vs Vector Leaves & Serialisasi UBJ/JSON ===\none_output_per_tree (K*C pohon) | RMSE=1.3460 | Pohon=150 | UBJ=355.2KB vs JSON=461.7KB | ReloadDiff=0.0e+00 | SHA256=b62cf40e5ce3\nmulti_output_tree (Vector Leaf) | RMSE=1.3580 | Pohon= 50 | UBJ=157.7KB vs JSON=266.3KB | ReloadDiff=0.0e+00 | SHA256=c6fb52c25848",
          "actualOutput": "=== Benchmark Multi-Target XGBoost 3.4.0: One-Per-Tree vs Vector Leaves & Serialisasi UBJ/JSON ===\none_output_per_tree (K*C pohon) | RMSE=1.3460 | Pohon=150 | UBJ=355.2KB vs JSON=461.7KB | ReloadDiff=0.0e+00 | SHA256=b62cf40e5ce3\nmulti_output_tree (Vector Leaf) | RMSE=1.3580 | Pohon= 50 | UBJ=157.7KB vs JSON=266.3KB | ReloadDiff=0.0e+00 | SHA256=c6fb52c25848",
          "explanation": "Menjalankan XGBRegressor nyata (3.4.0) membandingkan multi_strategy='one_output_per_tree' vs 'multi_output_tree' pada 3 target berkorelasi (RMSE, jumlah pohon, ukuran file .ubj vs .json) serta memverifikasi bit-exact reload dan SHA-256.",
